class Solution:
    def checkValid(self, matrix: List[List[int]]) -> bool:
        n = len(matrix)
        for i in range(n):
            if len(set(matrix[i])) != n:
                return False
        for j in range(n):
            if len({matrix[i][j] for i in range(n)}) != n:
                return False
        return True

