class Solution {
public:
    bool checkValid(vector<vector<int>>& matrix) {
        int n = matrix.size();
        for (int i = 0; i < n; i++) {
            unordered_set<int> s(matrix[i].begin(), matrix[i].end());
            if ((int)s.size() != n) return false;
        }
        for (int j = 0; j < n; j++) {
            unordered_set<int> s;
            for (int i = 0; i < n; i++) s.insert(matrix[i][j]);
            if ((int)s.size() != n) return false;
        }
        return true;
    }
};

