class Solution {
    public boolean checkValid(int[][] matrix) {
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            Set<Integer> s = new HashSet<>();
            for (int v : matrix[i]) s.add(v);
            if (s.size() != n) return false;
        }
        for (int j = 0; j < n; j++) {
            Set<Integer> s = new HashSet<>();
            for (int i = 0; i < n; i++) s.add(matrix[i][j]);
            if (s.size() != n) return false;
        }
        return true;
    }
};

