class Solution:
    def checkValid(self, matrix: List[List[int]]) -> bool:
        n = len(matrix)
        seen = [-1] * (n + 1)
        for k in range(2 * n):
            for i in range(n):
                v = matrix[k][i] if k < n else matrix[i][k - n]
                if seen[v] == k:
                    return False
                seen[v] = k
        return True

