class Solution {
public:
    bool checkValid(vector<vector<int>>& matrix) {
        int n = matrix.size();
        vector<int> seen(n + 1, -1);
        for (int k = 0; k < 2 * n; k++)
            for (int i = 0; i < n; i++) {
                int v = k < n ? matrix[k][i] : matrix[i][k - n];
                if (seen[v] == k) return false;
                seen[v] = k;
            }
        return true;
    }
};

